package com.bankease.dto; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDateTime; public final class BankDtos{public record CreateAccountResponse(Long id,String accountNumber,BigDecimal balance,String email,LocalDateTime createdAt){} public record AccountResponse(Long id,String accountNumber,BigDecimal balance,boolean active,LocalDateTime createdAt){} public record MoneyRequest(@NotNull @DecimalMin(value="0.01") BigDecimal amount,@Size(max=255) String description){} public record TransferRequest(@NotBlank String fromAccount,@NotBlank String toAccount,@NotNull @DecimalMin(value="0.01") BigDecimal amount,@Size(max=255) String description){} public record TransactionResponse(Long id,String type,BigDecimal amount,BigDecimal balanceAfter,String relatedAccount,String description,String referenceCode,LocalDateTime createdAt){}}